# Analyze each transformation in detail
inputs = ['gzdhwx', 'xcie', 'aijwag', 'vbia', 'wwwc']
outputs = ['gjadhwx', 'vdje', 'adfkjwag', 'vbb', 'wwwc']

# Let's examine the differences more systematically
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = None
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break

        if diff_pos is not None:
            print(f"  First difference at position {diff_pos}")
            print(f"  Input char: '{inp[diff_pos]}'")
            print(f"  Output char: '{out[diff_pos]}'")

            # Check if it's insertion/deletion
            if len(inp) < len(out):
                print("  This looks like an insertion")
            elif len(inp) > len(out):
                print("  This looks like a deletion")
            else:
                print("  This looks like a substitution")
    else:
        print("  No change")

